import json, re

with open('/app/all_products.json') as f:
    content = f.read()

# Each product starts with { and ends with }
# Use a state machine to extract JSON objects
products = []
i = 0
depth = 0
buf = ''
while i < len(content):
    ch = content[i]
    if ch == '{':
        depth += 1
        buf += ch
    elif ch == '}':
        depth -= 1
        buf += ch
        if depth == 0 and buf.strip():
            try:
                p = json.loads(buf)
                products.append(p)
            except:
                pass
            buf = ''
            depth = 0
    else:
        buf += ch
    i += 1

print(f'Number of products: {len(products)}')
for p in products:
    meta = {m['key']: m['value'] for m in p.get('meta_data', [])}
    sale = p.get('sale_price', '')
    regular = p.get('regular_price', '')
    dr = ''
    if sale and regular:
        try:
            r, s = float(regular), float(sale)
            if r > 0:
                dr = str(round((r-s)/r, 2))
        except:
            pass
    print(f'ID {p["id"]}: {p["name"]} created={p["date_created"]} sale30={meta.get("sales_last_30_days","?")} stock={p["stock_quantity"]} price={p["price"]} reg={p["regular_price"]} sale={p["sale_price"]} dr={dr}')
